ce_exchange_number": "730000", "table": "processes", "version": "00.00.001"}]}, "project_ref": "qgzvkongdjqiiamzbbts", "request_id": "fcfbc113-8d7e-575c-a7f3-ba5abfbf2265", "schema_version": "dataset-alias-execution-preflight.v2", "target_visibility": "owner_draft"}$wire$::jsonb as request;
create temp table v2_ctx as
  select 'fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid as request_id,
         (select request->'plan'->>'plan_sha256' from v2_wire) as plan_sha256;

create or replace function pg_temp.as_actor() returns void language plpgsql as $$
begin
  perform set_config('request.jwt.claim.role', 'authenticated', true);
  perform set_config('request.jwt.claim.sub', 'c536ee37-64ab-427b-b7e3-4e2bb4fdffb7', true);
  perform set_config('request.jwt.claim.email', 'fixture-owner@example.invalid', true);
end $$;

create or replace function pg_temp.gate_projection(p_result jsonb)
returns jsonb language sql immutable as $$
  select jsonb_build_object(
    'expected_sha256', p_result->>'expected_sha256',
    'observed_sha256', p_result->>'observed_sha256',
    'status', p_result->>'status',
    'captured_at', p_result->>'captured_at')
$$;

-- The reviewed request passes the ordinary protected path up to admission.
select pg_temp.as_actor();
create temp table v2_pf as
  select api.cmd_dataset_alias_execution_preflight_v2_guarded((select request from v2_wire)) as result;
select is((select result->>'ok' from v2_pf), 'true', 'the reviewed request still passes the protected preflight');
create temp table v2_g1 as select api.cmd_dataset_alias_execution_gate_v2_guarded(
  (select request_id from v2_ctx), (select result->>'preflight_token' from v2_pf), 'primary_support_plan') as result;
create temp table v2_g2 as select api.cmd_dataset_alias_execution_gate_v2_guarded(
  (select request_id from v2_ctx), (select result->>'preflight_token' from v2_pf), 'execution_unused') as result;
create temp table v2_g3 as select api.cmd_dataset_alias_execution_gate_v2_guarded(
  (select request_id from v2_ctx), (select result->>'preflight_token' from v2_pf), 'derivative_quiescence') as result;
select is(
  (select result->>'status' from v2_g1) || '/' || (select result->>'status' from v2_g2) || '/' || (select result->>'status' from v2_g3),
  'passed/passed/passed',
  'the three gates pass before the induced failure'
);
create temp table v2_admit as
  select api.cmd_dataset_alias_execution_admit_v2_guarded(jsonb_build_object(
    'schema_version', 'dataset-alias-execution-admit.v2',
    'request_id', (select request_id::text from v2_ctx),
    'preflight_token', (select result->>'preflight_token' from v2_pf),
    'preflight_proof_sha256', (select result->>'preflight_proof_sha256' from v2_pf),
    'gate_results', jsonb_build_object(
      'primary_support_plan', pg_temp.gate_projection((select result from v2_g1)),
      'execution_unused', pg_temp.gate_projection((select result from v2_g2)),
      'derivative_quiescence', pg_temp.gate_projection((select result from v2_g3))))) as result;
select is((select result->>'status' from v2_admit), 'dispatched', 'the execution is admitted once');

-- The state every action must be restored to, captured before the executor runs.
create temp table v2_before as
  select action->>'table' as tbl, (action->>'id')::uuid as id,
         action->'expected_json_ordered' as before_image
  from jsonb_array_elements((select request->'plan'->'actions' from v2_wire)) as action;
create temp table v2_audits_before as select count(*)::integer as audits from private.command_audit_log;

-- A transaction-local fault: the derivative orchestration's child INSERT fails.
create or replace function pg_temp.v2_fail_derivative_child()
returns trigger language plpgsql as $$
begin
  raise exception 'fixture-induced derivative sub-batch failure' using errcode = '23505';
end
$$;
create trigger v2_fail_derivative_child before insert on util.dataset_derivative_rebuild_requests
  for each row execute function pg_temp.v2_fail_derivative_child();

select set_config('request.headers',
  jsonb_build_object('apikey', util.project_secret_key(), 'authorization', 'Bearer ' || util.project_secret_key())::text, true);
create temp table v2_execute as
  select api.cmd_dataset_alias_execution_execute_v2(
    (select request_id from v2_ctx),
    (select convert_from(queued.body, 'UTF8')::jsonb->>'p_nonce'
     from net.http_request_queue as queued
     join util.dataset_alias_execution_v2_requests as request on request.net_request_id = queued.id
     where request.id = (select request_id from v2_ctx))) as result;

drop trigger v2_fail_derivative_child on util.dataset_derivative_rebuild_requests;

select is((select result->>'ok' from v2_execute), 'false', 'the executor reports the induced failure');
select is((select result->>'status' from v2_execute), 'failed', 'the execution is classified failed');
select is((select result->>'primary_rolled_back' from v2_execute), 'true', 'the executor reports the primary as rolled back');
select is(
  (select count(*)::integer from util.dataset_derivative_rebuild_requests as child
    where child.plan_sha256 = (select plan_sha256 from v2_ctx)),
  0,
  'no derivative child survives the induced failure'
);
select is(
  (select count(*)::integer from private.command_audit_log),
  (select audits from v2_audits_before),
  'no audit row survives the induced failure, so the whole alias topology rolled back'
);
select is(
  (select count(*)::integer from public.flows as flow
     join v2_before as before on before.id = flow.id and before.tbl = 'flows'
    where flow.json_ordered::jsonb is distinct from before.before_image)
  + (select count(*)::integer from public.processes as process
     join v2_before as before on before.id = process.id and before.tbl = 'processes'
    where process.json_ordered::jsonb is distinct from before.before_image),
  0,
  'every primary row holds exactly its before image again'
);
select is(
  (select count(*)::integer from util.dataset_alias_execution_v2_requests as request
    where request.id = (select request_id from v2_ctx) and request.primary_committed_at is not null),
  0,
  'the execution carries no commit mark'
);

select * from finish();
rollback;
